// TH15 v1.00b Stage 2 midboss nonspell (st02mbs.ecl.txt MBoss1, source lines 47-67).
// Card frame 0 = 40 frames after the shared MBoss timerReset (entry of MBoss1).
// OPENING_BUFFER delays the source timeline; the source segment then runs 1580 frames.

const TIME_LIMIT: int = 1704;      // 120 buffer + 1580 source window + 4 startup slack
const OPENING_BUFFER: int = 120;

// TH15 bullet-type aliases (sparse color channels per type, copied from touhou-bullets.ecl).
const TH15_BALL2: int = 432;       // source type 5, color 6
const TH15_BIG_BALL: int = 640;    // source type 18, color 3

// MBoss opening move: movePosTime(100, 4, 0, 128) from (-192,-64) is 40/100 done at the
// segment entry. Quad-out keeps its normalized shape when restarted from the 64% point,
// so the remaining 60 frames are exactly move_to(60, 0, 128, EASE_QUAD_OUT).
const ENTRY_X: fx = -69.12fx;      // -192 + 192 * (1-(1-0.4)^2)
const ENTRY_Y: fx = 58.88fx;       //  -64 + 192 * 0.64

// moveLimit(0, 128, 280, 256): per-frame clamp box; direction choice uses the inner
// quarter-width/height region (x +-70, y 64..192), per the moveRand recipe.
const LIMIT_X: fx = 140fx;
const LIMIT_Y0: fx = 0fx;
const LIMIT_Y1: fx = 256fx;
const INNER_X: fx = 70fx;
const INNER_Y0: fx = 64fx;
const INNER_Y1: fx = 192fx;

// ---- moveRand(60, 4, 1.0): fixed random direction per call, speed 1 -> 0 over 60 ticks ----
// Shared int slot 0 = next step count; fx slots 0/1 = unit direction (cos/sin).
sub mv_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var sp: fx = 0fx;
    if k < 60 { sp = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * sp;
    var ny: fx = $self_y + self_fx(1) * sp;
    if nx < 0fx - LIMIT_X { nx = 0fx - LIMIT_X; }
    if nx > LIMIT_X { nx = LIMIT_X; }
    if ny < LIMIT_Y0 { ny = LIMIT_Y0; }
    if ny > LIMIT_Y1 { ny = LIMIT_Y1; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mv_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mv_arm_next();
}

sub mv_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mv_arm_next();
    }
}

sub mv_rand() {
    // Source 412 direction pick: signed R in [-pi,pi] as raw BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < 0fx - INNER_X {
        a = r / 3;
    } else if $self_x > INNER_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }        // right branch is explicitly normalized
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;     // source WORD modulo 3, tiny bias kept
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < INNER_Y0 {
        if a < 0 { a = -a; }
    } else if $self_y > INNER_Y1 {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Source guard around +-pi/2 with epsilon 0.05 rad (nearest BAM bounds).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mv_begin(a as angle);
}

// ---- MBoss1_at(A, B, C): 8 expanding rings, then 8 rings at the last distance ----
// Source B is unused. etDist(F) is kept across the second loop (last value 16).
// EX type 2 ANIM a=1 gives every bullet a -4*speed displacement along its own angle,
// so the net birth distance is F - 4*v. E/N keep phase pi/2 and grow the road count;
// H/L keep 40 roads and rotate the ring phase by C per ring.
async sub mb1_at(a0: angle, step: angle) {
    var rank: int = global(GVAR_RANK);
    var v: fx = 1.5fx;                              // !E / !N
    if rank == RANK_HARD { v = 2.4fx; }             // !H
    else if rank >= RANK_LUNATIC { v = 2.6fx; }     // !LO
    var back: fx = 4fx * v;

    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_speed(0, v, 0fx);
    sh_angle(0, 90deg, 0deg);                       // etAngle(..., 1.5707964f, 0.0349)

    var a: angle = a0;
    for i in 0..8 {                                 // MBoss1_at_544 loop, $H = 8
        sh_count(0, 32 + i, 1);                     // $G = 32, +1 per ring
        sh_angle(0, 90deg, 0deg);
        sh_dist(0, (128 - 16 * i) as fx - back);    // %F = 128, -16 per ring
        sh_fire(0);
        wait(6);
    }
    for j in 0..8 {                                 // MBoss1_at_896 loop, $I = 8
        if rank >= RANK_HARD {
            sh_count(0, 40, 1);
            sh_angle(0, a, 0deg);                   // !HL etAngle(0, %A, 0)
        } else {
            sh_count(0, 40 + j, 1);                 // !EN $G = $G + 1
            sh_angle(0, 90deg, 0deg);
        }
        a = a + step;                               // %A = %A + %C (all ranks)
        sh_dist(0, 16fx - back);                    // etDist stays at 16
        sh_fire(0);
        wait(6);
    }
}

// ---- MBoss1_at2: aimed stream, !NHL only ----
async sub mb1_at2() {
    var rank: int = global(GVAR_RANK);
    var first: int = 300;                           // !E / !N (E never spawns this task)
    var period: int = 160;
    var n: int = 1;                                 // !E / !N / !H
    var v: fx = 1.6fx;                              // !N
    if rank == RANK_HARD {
        first = 60; period = 20; v = 3.0fx;         // !H
    } else if rank >= RANK_LUNATIC {
        first = 60; period = 13; n = 3; v = 4.0fx;  // !LO
    }

    sh_reset(0);
    sh_sprite(0, TH15_BIG_BALL, 3);
    sh_ring(0, 0);
    sh_aim(0, 1);
    sh_count(0, n, 1);
    sh_angle(0, 0deg, 20deg);                       // etAngle(1, %ANGLE_PLAYER, 0.34906584f)
    sh_speed(0, v, 0fx);
    sh_dist(0, 0fx - 4fx * v);                      // ANIM a=1 backshift
    wait(first);
    loop {                                          // $C = 6000; segment ends by timeout
        sh_fire(0);
        wait(period);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(20fx);                               // 501 setHitbox(40,40): r = 40*0.5
    set_hurtbox(24fx);                              // 500 setHurtbox(48,48): r = 48*0.5

    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);         // remaining MBoss opening move

    // EffChargePoint3 (anm sprites + playSound) is presentation only: omitted.
    wait(160);                                      // source wait(160) after the charge effect

    var rank: int = global(GVAR_RANK);
    if rank != RANK_EASY { spawn mb1_at2(); }       // !NHL async

    // MBoss1_196 loop, one cycle = 400 frames.
    loop {
        spawn mb1_at(0deg, -2deg);                  // MBoss1_at(0.0f, +2deg, -2deg)
        wait(120);
        mv_rand();                                  // moveRand(60, 4, 1.0f)
        mv_wait(60);
        wait(20);                                   // source wait(80) total
        spawn mb1_at(0deg, 2deg);                   // MBoss1_at(0.0f, -2deg, +2deg)
        wait(120);
        mv_rand();
        mv_wait(60);
        wait(20);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(ENTRY_X, ENTRY_Y, 11000, 0, 0, 0, boss_main);
    loop { wait(600); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
